<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<link rel="icon" href="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 100 100'%3E%3Ctext y='.9em' font-size='90'%3E%F0%9F%9F%A3%3C/text%3E%3C/svg%3E">
<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
<title>Picka's Hub</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Unbounded:wght@500;700&family=Plus+Jakarta+Sans:wght@400;500;600&display=swap" rel="stylesheet">
<style>
:root{--bg:#0d0915;--s:#151024;--l:#2a2140;--t:#eee9f8;--m:#9d93b8;--a:#9b6dff;--ok:#7be0a8;--bad:#ff7a9c;
box-sizing:border-box;padding-top:env(safe-area-inset-top,0px);padding-bottom:env(safe-area-inset-bottom,0px)}
*,*:before,*:after{box-sizing:inherit}
html{scroll-padding-top:env(safe-area-inset-top,0px)}
body{margin:0;background:radial-gradient(900px 500px at 12% -10%,#241547 0,transparent 60%),var(--bg);color:var(--t);font:400 16px/1.55 "Plus Jakarta Sans",system-ui,sans-serif;min-height:100vh}
button,input,select,textarea{font:inherit;color:inherit}
.bar{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:14px 20px;border-bottom:1px solid var(--l);position:sticky;top:0;background:#0d0915ee;z-index:5}
.bar span{color:var(--m);font-size:14px}
.sw{display:flex;border:1px solid var(--l);border-radius:6px;overflow:hidden}
.sw button{background:none;border:0;padding:7px 12px;cursor:pointer;color:var(--m);font-size:14px}
.sw button.on{background:var(--a);color:#fff}
main{max-width:640px;margin:0 auto;padding:44px 20px 80px}
h1{font:700 clamp(32px,9.5vw,60px)/1.05 "Unbounded",system-ui,sans-serif;margin:0 0 16px;letter-spacing:-.02em;animation:rise 1s cubic-bezier(.2,.8,.2,1) backwards,glow 3s ease-in-out infinite alternate}
h2{font:500 24px/1.2 "Unbounded",system-ui,sans-serif;margin:0 0 8px}
h3{font-size:15px;font-weight:600;margin:28px 0 10px}
.lead{color:var(--m);margin:0 0 34px;max-width:46ch}
.pills{display:flex;flex-wrap:wrap;justify-content:center;gap:12px;max-width:540px;margin:0 auto}
.row{position:relative;overflow:hidden;display:inline-flex;align-items:center;gap:12px;background:#120c1f;border:1px solid var(--l);border-radius:999px;padding:12px 26px 12px 12px;color:#c9bfe0;font-weight:500;font-size:17px;cursor:pointer;text-decoration:none;transition:transform .25s,border-color .25s,box-shadow .25s,color .25s;animation:pop .7s cubic-bezier(.2,.9,.3,1.2) backwards;animation-delay:calc(var(--i) * .09s + .4s)}
.row i{width:34px;height:34px;border-radius:50%;background:#1e1530;display:grid;place-items:center}
.row i:before{content:"";width:9px;height:9px;border-radius:50%;background:#6a5a8f;transition:background .25s,box-shadow .25s}
.row:after{content:"";position:absolute;inset:0;background:linear-gradient(110deg,transparent 30%,#9b6dff40 50%,transparent 70%);transform:translateX(-120%);transition:transform .7s}
.row:hover{transform:translateY(-3px) scale(1.04);border-color:var(--a);box-shadow:0 0 0 1px #9b6dff55,0 10px 32px #9b6dff55;color:#fff}
.row:hover:after{transform:translateX(120%)}
.row:hover i:before{background:var(--a);box-shadow:0 0 14px var(--a)}
.row:active{transform:scale(.95)}
.hero{min-height:calc(100vh - 170px);display:flex;flex-direction:column;justify-content:center;text-align:center}
.hero .lead{margin:0 auto 34px}
.v:not([hidden]){animation:fade .45s ease backwards}
#fire{position:fixed;left:0;bottom:0;width:100%;height:55vh;pointer-events:none;z-index:0;-webkit-mask-image:linear-gradient(to top,#000 35%,transparent);mask-image:linear-gradient(to top,#000 35%,transparent)}
main{position:relative;z-index:1}
.back{background:none;border:0;color:var(--m);cursor:pointer;padding:0;margin-bottom:26px}
.back:hover{color:var(--a)}
.box{background:var(--s);border:1px solid var(--l);border-radius:8px;padding:16px}
code{display:block;font:13px/1.6 ui-monospace,Menlo,monospace;color:#d9ccff;word-break:break-all;white-space:pre-wrap}
.btn{background:var(--a);color:#fff;border:0;border-radius:6px;padding:10px 16px;cursor:pointer;font-weight:500}
.btn:hover{filter:brightness(1.12)}
.btn.ghost{background:none;border:1px solid var(--l);color:var(--t)}
.btn.sm{padding:6px 10px;font-size:13px}
input,select,textarea{width:100%;background:var(--s);border:1px solid var(--l);border-radius:6px;padding:10px 12px;margin-bottom:10px}
textarea{min-height:110px;resize:vertical}
:focus-visible{outline:2px solid var(--a);outline-offset:2px}
label{display:block;color:var(--m);font-size:14px;margin-bottom:4px}
.price{display:flex;justify-content:space-between;padding:9px 0;border-top:1px solid var(--l)}
.price span:last-child{color:var(--m)}
.game{display:grid;grid-template-columns:48px 1fr auto;gap:14px;align-items:center;border-top:1px solid var(--l);padding:12px 0}
.thumb{width:48px;height:48px;border-radius:8px;background:linear-gradient(135deg,#3a2570,#1b1236)}
.game small{color:var(--m);display:block}
.tag{font-size:13px;border:1px solid var(--l);border-radius:99px;padding:2px 10px;color:var(--m)}
.tag.k{color:var(--bad);border-color:#5a2a3d}.tag.f{color:var(--ok);border-color:#235a40}.tag.b{color:var(--a);border-color:#4b3685}
.tabs{display:flex;gap:18px;border-bottom:1px solid var(--l);margin:0 0 24px;overflow-x:auto}
.tabs button{background:none;border:0;border-bottom:2px solid transparent;color:var(--m);padding:8px 0;cursor:pointer;white-space:nowrap}
.tabs button.on{color:var(--t);border-color:var(--a)}
.fb{border-top:1px solid var(--l);padding:12px 0}.fb small{color:var(--m)}
.cards{display:grid;gap:12px}
.card{display:block;text-decoration:none;color:var(--t);background:var(--s);border:1px solid var(--l);border-radius:8px;padding:18px;transition:border-color .2s}
.card:hover{border-color:var(--a)}.card small{color:var(--m);display:block}
.prov{display:flex;align-items:center;gap:16px;font-size:18px}.prov img{width:44px;height:44px;object-fit:contain}
.ag{grid-template-columns:48px 1fr}.ag .ctl{grid-column:1/-1;display:flex;gap:8px;flex-wrap:wrap}.ag select{margin:0;width:auto}
.thumb.l{display:grid;place-items:center;font:700 18px "Unbounded",sans-serif;color:#d9ccff}
a.game{display:grid;color:inherit;text-decoration:none;padding:12px;border:1px solid var(--l);border-radius:10px;margin-bottom:10px;background:var(--s);transition:border-color .2s,transform .2s}
a.game:hover{border-color:var(--a);transform:translateY(-2px)}
img.thumb{object-fit:cover;display:block}.st-Working{color:var(--ok)}.st-Updating{color:var(--a)}.st-Down{color:var(--bad)}
.bopt b{display:block;margin-bottom:12px;font:500 18px "Unbounded",system-ui,sans-serif}.bopt select{margin-bottom:10px}
.pr{display:flex;justify-content:space-between;width:100%;background:var(--s);border:1px solid var(--l);border-radius:10px;padding:14px 16px;margin-bottom:10px;cursor:pointer;color:var(--t);transition:border-color .2s,box-shadow .2s}
.pr:hover{border-color:var(--a)}.pr.on{border-color:var(--a);box-shadow:0 0 0 1px #9b6dff66}.pr span:last-child{color:var(--m)}
.how{margin:0;padding:0;list-style:none;counter-reset:s}.how li{counter-increment:s;display:flex;align-items:center;gap:14px;padding:12px 0;border-top:1px solid var(--l);color:#c9bfe0}
.how li:before{content:counter(s);display:grid;place-items:center;flex:none;width:28px;height:28px;border-radius:50%;background:#1e1530;color:var(--a);font-weight:600;font-size:14px}
.sr{display:flex;gap:8px;margin-bottom:8px}.sr input{margin:0}.sr .btn{flex:none}.sub{color:var(--m);font-size:14px;margin:12px 0 8px}
.fb .btn{margin-left:6px}
.toast{position:fixed;left:50%;bottom:calc(24px + env(safe-area-inset-bottom,0px));transform:translateX(-50%);background:var(--a);color:#fff;padding:9px 16px;border-radius:6px;opacity:0;pointer-events:none;transition:opacity .2s}
.toast.on{opacity:1}
[hidden]{display:none!important}
.split{display:grid;gap:10px;grid-template-columns:1fr 1fr}
@media(max-width:480px){.split{grid-template-columns:1fr}}
@keyframes pop{from{opacity:0;transform:translateY(26px) scale(.8)}to{opacity:1;transform:none}}
@keyframes rise{from{opacity:0;transform:translateY(20px);filter:blur(14px)}to{opacity:1;transform:none;filter:none}}
@keyframes glow{from{text-shadow:0 0 18px #9b6dff44}to{text-shadow:0 0 46px #b58cffcc}}
@keyframes fade{from{opacity:0;transform:translateY(14px)}to{opacity:1;transform:none}}
@media(prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}}
.seg{display:flex;gap:6px;border:1px solid var(--l);border-radius:999px;padding:4px;width:max-content;margin:0 auto 28px;background:#120c1f}
.seg button{background:none;border:0;border-radius:999px;padding:8px 24px;color:var(--m);cursor:pointer;transition:.25s}
.seg button.on{background:var(--a);color:#fff;box-shadow:0 0 18px #9b6dff66}
.pg:not([hidden]){animation:fade .45s ease backwards}
.pls{display:grid;grid-template-columns:1fr 1fr;gap:10px}
.po{display:flex;align-items:center;gap:12px;background:#120c1f;border:1px solid var(--l);border-radius:14px;padding:12px;color:var(--t);cursor:pointer;transition:.25s}
.po img{width:34px;height:34px;object-fit:contain}.po:hover{border-color:var(--a)}
.po.on{border-color:var(--a);box-shadow:0 0 0 1px #9b6dff66,0 8px 26px #9b6dff44;transform:translateY(-2px)}
.dur{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:22px}
.dur button{background:#120c1f;border:1px solid var(--l);border-radius:14px;padding:14px;color:var(--t);cursor:pointer;transition:.25s;text-align:left}
.dur button span{display:block;color:var(--m);font-size:13px}.dur button.on{border-color:var(--a);box-shadow:0 0 0 1px #9b6dff66,0 8px 26px #9b6dff44}
.btn:disabled{opacity:.35;cursor:not-allowed;filter:none}
.pb{height:6px;background:#1e1530;border-radius:99px;overflow:hidden;margin:12px 0}
.pb i{display:block;height:100%;width:0;background:linear-gradient(90deg,#6d3fe0,#c9a6ff);box-shadow:0 0 14px #9b6dff;transition:width .6s}
.tl{position:relative;padding-left:46px;margin-top:22px}
.tl:before{content:"";position:absolute;left:15px;top:10px;bottom:10px;width:2px;background:var(--l)}
.st{position:relative;margin-bottom:14px;background:var(--s);border:1px solid var(--l);border-radius:14px;padding:14px 16px;opacity:.45;transition:.4s}
.st .dot{position:absolute;left:-46px;top:12px;width:32px;height:32px;border-radius:50%;background:#1e1530;border:2px solid var(--l);display:grid;place-items:center;font-size:13px;font-weight:600;transition:.4s}
.st .sd{margin:2px 0 10px;color:var(--m);font-size:14px}.st:not(.act) .btn{display:none}
.st.act{opacity:1;border-color:var(--a);box-shadow:0 0 0 1px #9b6dff55,0 10px 30px #9b6dff33}
.st.act .dot{border-color:var(--a);animation:pulse 1.6s infinite}
.st.done{opacity:1}.st.done .dot{background:var(--a);border-color:var(--a);box-shadow:0 0 16px var(--a)}
.st.ver .btn{animation:blink 1s infinite}
.kc{text-align:center;padding:30px 16px;border-radius:18px;background:linear-gradient(#17102b,#100a1d);border:1px solid #4b3685;animation:pop .8s cubic-bezier(.2,.9,.3,1.2) backwards,kg 2.6s ease-in-out infinite alternate}
.kc small{color:var(--m)}.kv{font:600 clamp(18px,5.6vw,28px) ui-monospace,Menlo,monospace;letter-spacing:.06em;color:#f1e9ff;text-shadow:0 0 22px #9b6dffaa;word-break:break-all;margin:10px 0 6px}
.kx{color:var(--ok);font-size:14px}
.kr{background:var(--s);border:1px solid var(--l);border-radius:14px;padding:14px 16px;margin-bottom:12px}
.kt{display:flex;justify-content:space-between;align-items:center;gap:10px}.kr code{font-size:15px;color:#e5d9ff;word-break:normal}
.chip{font-size:12px;font-weight:600;border-radius:99px;padding:3px 10px;border:1px solid}.chip.on{color:var(--ok);border-color:#235a40}.chip.off{color:var(--bad);border-color:#5a2a3d}
.ka{display:flex;gap:8px;margin-top:10px}.kr small{color:var(--m)}
.bp{text-align:center;padding:34px 16px;border-radius:18px;background:linear-gradient(#2a0f1e,#170a14);border:1px solid #6a2a45;box-shadow:0 0 50px #ff7a9c22}
.bt{font:700 clamp(40px,14vw,64px) "Unbounded",sans-serif;color:var(--bad);text-shadow:0 0 24px #ff7a9c88;margin:8px 0}
.c{text-align:center}.demo{margin-top:18px;text-align:center}
@keyframes pulse{0%,100%{box-shadow:0 0 0 0 #9b6dff88}50%{box-shadow:0 0 0 9px #9b6dff00}}
@keyframes blink{50%{opacity:.5}}
@keyframes kg{from{box-shadow:0 0 30px #9b6dff33}to{box-shadow:0 0 70px #9b6dff77}}
.ann{background:#2a1a52;border-bottom:1px solid #4b3685;color:#e5d9ff;text-align:center;padding:10px 16px;font-size:14px;position:relative;z-index:6}
.mtov{position:fixed;inset:0;z-index:20;background:var(--bg);display:grid;place-items:center;text-align:center;padding:24px}
.tsw{margin:10px 0}.back{display:inline-block}.bn{color:var(--bad);font-weight:600;margin:6px 0 12px}
.tag.y{color:#ffd166;border-color:#6a5420}
</style>
</head>
<body>
<canvas id="fire"></canvas>
<div class="ann" id="annb" hidden></div>

<main id="dash">
<section class="v hero" data-v="home">
<h1>Picka's Hub</h1>
<p class="lead">Get a key, copy the script, and see which games are supported.</p>
<div class="pills">
<button class="row" style="--i:0" data-go="getkey"><i></i>Get Key</button>
<button class="row" style="--i:1" data-go="script"><i></i>Get Script</button>
<button class="row" style="--i:2" data-go="buy"><i></i>Buy Key</button>
<button class="row" style="--i:3" data-go="feedback"><i></i>Feedback</button>
<button class="row" style="--i:4" data-go="games"><i></i>Supported</button>
<button class="row" style="--i:5" data-go="community"><i></i>Community</button>
</div>
</section>

<section class="v" data-v="getkey" hidden>
<button class="back" data-go="home">Back</button>
<h2 class="c">Get Key</h2>
<div class="seg" id="gseg"><button class="on" data-gt="p">Provider</button><button data-gt="k">Keys</button></div>
<div id="gp" class="pg"><p id="rnb" class="sub c" hidden><span id="rnt"></span> <button class="btn ghost sm" id="rnc">Cancel</button></p><h3>Provider</h3><div class="pls" id="pl"></div>
<h3>Duration</h3><div class="dur"><button data-d="12"><b>12 Hours</b><span>1 step</span></button><button data-d="24"><b>24 Hours</b><span>2 steps</span></button></div>
<button class="btn" id="go" disabled>Proceed</button></div>
<div id="gkeys" class="pg" hidden><div id="kl"></div></div>
<div id="gtask" class="pg" hidden><button class="back" data-go="getkey">Cancel</button><h2 id="th"></h2><div class="pb"><i id="pf"></i></div><div class="tl" id="tl"></div></div>
<div id="kreveal" class="pg" hidden><p class="lead c" id="krt" style="margin:0 auto 22px">Key created. Copy it and paste it into the script window.</p>
<div class="kc"><small>Your key</small><div class="kv" id="kv"></div><div class="kx" id="kx"></div></div>
<p class="c" style="margin-top:20px"><button class="btn" id="kcopy">Copy key</button> <button class="btn ghost" id="kview">View Keys</button></p>
<p class="lead c" style="margin:6px auto;font-size:14px">It binds to your Roblox account the first time you use it.</p></div>
</section>

<section class="v" data-v="script" hidden>
<button class="back" data-go="home">Back</button>
<h2>Get Script</h2><p class="lead">Paste this in your executor.</p>
<div class="box"><code id="ls"></code></div>
<p><button class="btn" id="copy">Copy script</button></p>
<h3>How to execute</h3>
<ol class="how"><li>Get a key from the Get Key page.</li><li>Copy the script with the Copy button above.</li><li>Open your executor and join a supported game.</li><li>Paste the script and execute it.</li><li>Paste your key when asked.</li></ol>
</section>

<section class="v" data-v="buy" hidden>
<button class="back" data-go="home">Back</button>
<h2>Buy premium key</h2>
<div id="b1">
<p class="lead">Choose how you want to pay.</p>
<div class="cards">
<div class="box bopt" data-o="r"><b>Buy with Robux</b>
<select class="pm"><option value="">Select payment method</option><option>Gamepass</option><option>Via Plus</option><option>Group payout</option></select>
<select class="mm"><option value="">Select message method</option><option>Discord</option><option>Telegram</option></select>
<button class="btn cont">Continue</button></div>
<div class="box bopt" data-o="c"><b>Buy with $</b>
<select class="pm"><option value="">Select payment method</option><option>GCash</option><option>Crypto</option><option>PayPal</option></select>
<select class="mm"><option value="">Select message method</option><option>Discord</option><option>Telegram</option></select>
<button class="btn cont">Continue</button></div>
</div>
</div>
<div id="b2" hidden>
<button class="back" id="bchange">Change method</button>
<p class="lead" id="bsum"></p>
<div id="bp"></div>
<button class="btn" id="order">Order</button>
</div>
</section>

<section class="v" data-v="feedback" hidden>
<button class="back" data-go="home">Back</button>
<h2>Feedback</h2><p class="lead">One message every 7 days.</p>
<label for="fm">Message</label><textarea id="fm"></textarea>
<button class="btn" id="send">Send feedback</button>
</section>

<section class="v" data-v="games" hidden>
<button class="back" data-go="home">Back</button>
<h2 class="c">Supported</h2>
<div class="seg" id="sseg"><button class="on" data-sg="g">Game</button><button data-sg="e">Executors</button></div>
<div id="sg" class="pg"><p class="lead c">Tap a game to open it on Roblox.</p><div id="pub"></div></div>
<div id="se" class="pg" hidden><p class="lead c">Tap an executor to open its page.</p><div id="epub"></div></div>
</section>

<section class="v" data-v="community" hidden>
<button class="back" data-go="home">Back</button>
<h2>Community</h2><p class="lead">Join us where updates land first.</p>
<div class="cards">
<a class="card" href="https://discord.gg/R3rDNwrV7y" target="_blank" rel="noopener"><b>Discord</b><small>Updates, support, and giveaways</small></a>
<a class="card" href="https://t.me/+MGEV4AC7LEllZDJl" target="_blank" rel="noopener"><b>Telegram</b><small>Announcements and quick help</small></a>
</div>
</section>
</main>

<main id="admin" hidden>
<section id="gate">
<h1>Admin</h1><p class="lead">Enter your admin key to continue.</p>
<input id="key" type="password" placeholder="Put key here" autocomplete="off">
<button class="btn" id="enter">Enter</button>
</section>
<section id="panel" hidden>
<h2>Admin Dashboard</h2>
<div class="tabs"><button class="on" data-t="c">Create Key</button><button data-t="y">Keys</button><button data-t="g">Supported</button><button data-t="l">Loader</button><button data-t="s">Shop</button><button data-t="k">Links</button><button data-t="f">Feedback</button><button data-t="a">Stats</button><button data-t="e">Settings</button></div>

<div class="t" data-t="g" hidden>
<div class="seg" id="asg"><button class="on" data-ag="g">Game</button><button data-ag="e">Executors</button></div>
<div id="ag1">
<div id="glist"></div>
<h3>Add a game</h3>
<label for="gl">Game link</label><input id="gl" placeholder="https://www.roblox.com/games/...">
<label for="gm">Label</label><select id="gm"><option>Key system</option><option>Keyless</option><option>Both</option></select>
<label for="gs">Status</label><select id="gs"><option>Working</option><option>Updating</option><option>Down</option></select>
<button class="btn" id="gadd">Add game</button></div>
<div id="ag2" hidden>
<div id="exl"></div>
<h3>Add an executor</h3>
<label for="ex1">Name</label><input id="ex1" autocomplete="off">
<label for="ex2">Logo (image URL, optional)</label><input id="ex2" placeholder="https://.../logo.png" autocomplete="off">
<label for="ex3">Link</label><input id="ex3" placeholder="https://..." autocomplete="off">
<label for="ex4">Status</label><select id="ex4"><option>Supported</option><option>Not supported</option><option>Not tested</option></select>
<button class="btn" id="exadd">Add executor</button>
</div>

</div>

<div class="t" data-t="l" hidden>
<label for="lo">Loadstring</label><textarea id="lo"></textarea>
<button class="btn" id="lsave">Save loader</button>
</div>

<div class="t" data-t="k" hidden>
<label for="k2">Discord link</label><input id="k2" value="https://discord.gg/R3rDNwrV7y">
<label for="k3">Telegram link</label><input id="k3" value="https://t.me/+MGEV4AC7LEllZDJl">
<button class="btn" id="ksave">Save links</button>
</div>

<div class="t" data-t="s" hidden>
<h3>Robux prices</h3><div id="sp-r"></div>
<h3>$ prices</h3><div id="sp-c"></div>
<h3>Add a price</h3>
<div class="split"><div><label for="ad">Duration</label><input id="ad" placeholder="e.g. 14 Day"></div><div><label for="ap">Price</label><input id="ap" placeholder="e.g. 250 Robux"></div></div>
<label for="ao">Add to</label><select id="ao"><option value="r">Robux</option><option value="c">$</option></select>
<button class="btn" id="sadd">Add price</button>
<h3>Payment methods</h3>
<p class="sub">Robux</p><div id="pm-r"></div><p class="sub">$</p><div id="pm-c"></div>
<div class="split"><input id="an" placeholder="e.g. Maya"><select id="ag"><option value="r">Robux</option><option value="c">$</option></select></div>
<button class="btn" id="padd">Add payment method</button>
<h3>Message methods</h3>
<div id="mm-l"></div>
<div class="split"><input id="mn" placeholder="Name"><input id="mu" placeholder="Link"></div>
<button class="btn" id="madd">Add message method</button>
</div>

<div class="t" data-t="c">
<div class="split"><div><label for="ct">Key type</label><select id="ct"><option>Normal</option><option>Premium</option></select></div><div><label for="cu">Type</label><select id="cu"><option>Day</option><option>Hour</option><option>Minutes</option><option>Forever</option></select></div></div>
<label for="cg">Game</label><select id="cg"><option value="all">All</option></select>
<label for="ca">Duration</label><input id="ca" type="number" min="1" value="1">
<button class="btn" id="cmk">Create key</button><div id="cout" style="margin-top:14px"></div>
</div>
<div class="t" data-t="y" hidden><input id="kq" placeholder="Search keys"><div id="kls"></div></div>
<div class="t" data-t="a" hidden><div id="sts"></div></div>
<div class="t" data-t="e" hidden>
<label for="cbu">Destination URL for provider links</label><div class="sr"><input id="cbu" readonly><button class="btn ghost sm" id="cbc">Copy</button></div>
<p class="sub">Linkvertise, Cuty.io and Lockr links must send users to this URL. Lootlabs adds it automatically.</p>
<h3>Lootlabs</h3><label for="sl1">Link</label><input id="sl1" placeholder="https://..." autocomplete="off"><label for="sl2">API token</label><input id="sl2" placeholder="" autocomplete="off">
<h3>Linkvertise</h3><label for="sv1">Link</label><input id="sv1" placeholder="https://..." autocomplete="off"><label for="sv2">Token</label><input id="sv2" placeholder="" autocomplete="off">
<h3>Cuty.io</h3><label for="sc1">Link</label><input id="sc1" placeholder="https://..." autocomplete="off"><label for="sc2">Token</label><input id="sc2" placeholder="" autocomplete="off">
<h3>Lockr</h3><label for="sk1">Link</label><input id="sk1" placeholder="https://..." autocomplete="off"><label for="sk2">Token</label><input id="sk2" placeholder="" autocomplete="off">
<h3>Human check (Cloudflare Turnstile)</h3><label for="ts1">Site key</label><input id="ts1" placeholder="" autocomplete="off"><label for="ts2">Secret key</label><input id="ts2" placeholder="" autocomplete="off">
<h3>Webhooks</h3><label for="h1">New key webhook URL</label><input id="h1" placeholder="" autocomplete="off"><label for="h2">Execute webhook URL</label><input id="h2" placeholder="" autocomplete="off">
<h3>Discord bot</h3><label for="dc1">Bot token</label><input id="dc1" type="password" autocomplete="off"><label for="dc2">Application ID</label><input id="dc2" placeholder="" autocomplete="off"><label for="dc3">Public key</label><input id="dc3" placeholder="" autocomplete="off">
<label for="dcu">Interactions Endpoint URL</label><input id="dcu" readonly>
<button class="btn ghost sm" id="dcreg" style="margin:8px 0 14px">Save and register commands</button>
<h3>Announcement banner</h3><label for="an1">Show banner</label><select id="an1"><option>Off</option><option>On</option></select><label for="an2">Banner text</label><input id="an2" placeholder="" autocomplete="off">
<h3>Maintenance mode</h3><label for="mt1">Maintenance mode</label><select id="mt1"><option>Off</option><option>On</option></select><label for="mt2">Message shown to visitors</label><input id="mt2" placeholder="" autocomplete="off">
<button class="btn" id="esave" style="margin-top:6px">Save settings</button>
<h3>Provider responses (debug)</h3><div id="dbg"></div>
</div>
<div class="t" data-t="f" hidden>
<div id="fl"></div>
</div>
</section>
</main>

<div class="mtov" id="mtov" hidden><div><h1>Maintenance</h1><p class="lead" id="mtt" style="margin:0 auto"></p></div></div>
<div class="toast" id="toast"></div>
<script>
(function(){
var $=function(s,r){return(r||document).querySelector(s)},$$=function(s,r){return[].slice.call((r||document).querySelectorAll(s))};
var admin=/^\/admin/.test(location.pathname),key="",S=null,cur=null,pick=0,LG={"lootlabs": "data:image/png;base64,", "linkvertise": "data:image/png;base64,", "cutyio": "data:image/png;base64,", "lockr": "data:image/png;base64,"},NM={lootlabs:"Lootlabs",linkvertise:"Linkvertise",cutyio:"Cuty.io",lockr:"Lockr"};
var prov="",dur=0,TS="",tsw=null,bi=0,lastKey="",renewKey="";
$("#dash").hidden=admin;$("#admin").hidden=!admin;
function toast(m){var t=$("#toast");t.textContent=m;t.classList.add("on");setTimeout(function(){t.classList.remove("on")},2400)}
function mk(t,c,x){var e=document.createElement(t);if(c)e.className=c;if(x!=null)e.textContent=x;return e}
function lsg(k){try{return localStorage.getItem(k)||""}catch(e){return""}}
function lss(k,v){try{if(v===null)localStorage.removeItem(k);else localStorage.setItem(k,v)}catch(e){}}
function api(p,o){o=o||{};var h={"content-type":"application/json"};if(key)h["x-admin-key"]=key;o.headers=h;return fetch("/api"+p,o).then(function(r){return r.json().catch(function(){return{}}).then(function(d){if(!r.ok){var e=new Error(d.error||"error");e.status=r.status;e.data=d;throw e}return d})})}
function view(n){$$(".v").forEach(function(e){e.hidden=e.dataset.v!==n});scrollTo(0,0)}
var PATH={home:"/",getkey:"/getkey",script:"/script",buy:"/buykey",feedback:"/feedback",games:"/games",community:"/community"},ROUTE={"/":"home","/getkey":"getkey","/keys":"keys","/script":"script","/buykey":"buy","/feedback":"feedback","/games":"games","/executors":"executors","/community":"community"};
function nav(n,push){var v=n==="keys"?"getkey":n==="executors"?"games":n;view(v);if(v==="getkey")tabg(n==="keys"?"k":"p",true);if(v==="games")tabs(n==="executors"?"e":"g",true);var p=n==="keys"?"/keys":n==="executors"?"/executors":PATH[v];if(push!==false&&location.pathname!==p)history.pushState(null,"",p)}
function tabs(t,quiet){$$("#sseg button").forEach(function(b){b.classList.toggle("on",b.dataset.sg===t)});$("#sg").hidden=t!=="g";$("#se").hidden=t!=="e";if(!quiet){var p=t==="e"?"/executors":"/games";if(location.pathname!==p)history.pushState(null,"",p)}}
$$("#sseg button").forEach(function(b){b.onclick=function(){tabs(b.dataset.sg)}});
var EXC={"Supported":"f","Not supported":"k","Not tested":"y"};
function epub(){var p=$("#epub");p.innerHTML="";S.executors.forEach(function(x){var a=mk("a","game");if(x.link){a.href=x.link;a.target="_blank";a.rel="noopener"}var t;if(x.logo){t=mk("img","thumb");t.src=x.logo;t.alt="";t.loading="lazy";t.onerror=function(){t.replaceWith(mk("div","thumb l",(x.name||"?").charAt(0)))}}else t=mk("div","thumb l",(x.name||"?").charAt(0));a.appendChild(t);var d=mk("div");d.appendChild(mk("span","n",x.name));a.appendChild(d);a.appendChild(mk("span","tag "+(EXC[x.status]||"y"),x.status));p.appendChild(a)});if(!S.executors.length)p.appendChild(mk("p","lead c","No executors yet."))}
function route(){var n=ROUTE[location.pathname.replace(/\/+$/,"")||"/"]||"home";nav(n,false)}
document.addEventListener("click",function(e){var g=e.target.closest("[data-go]");if(g)nav(g.dataset.go)});
window.addEventListener("popstate",function(){if(location.pathname!=="/cb")route()});
function fill(s,ph,a){s.innerHTML="";var o=mk("option",null,ph);o.value="";s.appendChild(o);a.forEach(function(t){s.appendChild(mk("option",null,t))})}
function buyDraw(){$$(".bopt").forEach(function(b){var o=b.dataset.o;fill($(".pm",b),"Select payment method",S.shop[o].pm);fill($(".mm",b),"Select message method",S.shop.mm.map(function(z){return z[0]}))})}
function num(n){n=n||0;return n>=1e9?(n/1e9).toFixed(1)+"B":n>=1e6?(n/1e6).toFixed(1)+"M":n>=1e3?(n/1e3).toFixed(1)+"K":String(n)}
function thumb(g){if(g.img){var i=mk("img","thumb");i.src=g.img;i.alt="";i.loading="lazy";return i}return mk("div","thumb l",(g.name||"?").charAt(0))}
function pub(){var p=$("#pub");p.innerHTML="";S.games.forEach(function(g){var a=mk("a","game");a.href=g.link;a.target="_blank";a.rel="noopener";a.appendChild(thumb(g));var d=mk("div");d.appendChild(mk("span","n",g.name||"Game"));var s=mk("small");s.appendChild(document.createTextNode(g.playing!=null?num(g.playing)+" playing \u00b7 "+num(g.visits)+" visits \u00b7 ":""));s.appendChild(mk("span","st-"+g.status,g.status));d.appendChild(s);a.appendChild(d);a.appendChild(mk("span","tag "+({"Key system":"k","Keyless":"f","Both":"b"}[g.label]||""),g.label));p.appendChild(a)});if(!S.games.length)p.appendChild(mk("p","lead","No games yet."))}
function render(){
S.executors=S.executors||[];$("#ls").textContent=S.loader||"";
var c=$$("[data-v=community] .card");c[0].href=S.links.discord||"#";c[1].href=S.links.telegram||"#";
var a=$("#annb");a.hidden=!(S.ann.on&&S.ann.text);a.textContent=S.ann.text;
$("#mtt").textContent=S.maint.text||"We are under maintenance. Please check back soon.";$("#mtov").hidden=!S.maint.on;
pub();epub();buyDraw();pdraw()}

/* Buy key */
function rp(){var p=$("#bp"),L=S.shop[cur.o].prices;p.innerHTML="";L.forEach(function(x,i){var e=mk("button","pr"+(i==pick?" on":""));e.appendChild(mk("span",null,x[0]));e.appendChild(mk("span",null,x[1]));e.onclick=function(){pick=i;rp()};p.appendChild(e)})}
$$(".bopt").forEach(function(b){$(".cont",b).onclick=function(){var pm=$(".pm",b).value,mm=$(".mm",b).value;if(!pm||!mm)return toast("Select payment and message method");cur={o:b.dataset.o,pm:pm,mm:mm};pick=0;$("#bsum").textContent=(cur.o=="r"?"Robux":"$")+" / "+pm+" / "+mm;rp();$("#b1").hidden=true;$("#b2").hidden=false}});
$("#bchange").onclick=function(){$("#b2").hidden=true;$("#b1").hidden=false};
$("#order").onclick=function(){var x=S.shop[cur.o].prices[pick];if(!x)return toast("Pick a plan");var t="Hi, I want to buy a "+x[0]+" key ("+x[1]+") using "+cur.pm+".";try{navigator.clipboard.writeText(t)}catch(e){}toast("Order message copied");var m=S.shop.mm.filter(function(z){return z[0]==cur.mm})[0],u=m?m[1]:"";if(u)window.open(/t\.me\//.test(u)?u+"?text="+encodeURIComponent(t):u,"_blank")};
$("#copy").onclick=function(){var t=$("#ls").textContent;if(!t)return toast("Script not available yet");navigator.clipboard.writeText(t).then(function(){toast("Script copied")},function(){toast("Could not copy")})};
$("#send").onclick=function(){var m=$("#fm").value.trim();if(!m)return toast("Write a message first");api("/feedback",{method:"POST",body:JSON.stringify({message:m})}).then(function(){$("#fm").value="";toast("Feedback sent")}).catch(function(e){toast(e.status==429?"You can send feedback once every 7 days":"Could not send")})};

/* Get key */
function gshow(id){["gp","gkeys","gtask","kreveal"].forEach(function(x){$("#"+x).hidden=x!==id});$("#gseg").hidden=!(id==="gp"||id==="gkeys");scrollTo(0,0)}
function tabg(t,quiet){$$("#gseg button").forEach(function(b){b.classList.toggle("on",b.dataset.gt===t)});gshow(t==="p"?"gp":"gkeys");if(t==="k")kdraw();if(!quiet){var p=t==="k"?"/keys":"/getkey";if(location.pathname!==p)history.pushState(null,"",p)}}
function rnShow(){$("#rnb").hidden=!renewKey;$("#rnt").textContent="Renewing "+renewKey}
$("#rnc").onclick=function(){renewKey="";rnShow()};
$$("#gseg button").forEach(function(b){b.onclick=function(){tabg(b.dataset.gt)}});
function pdraw(){var l=$("#pl");l.innerHTML="";if(!S.prov.length){l.appendChild(mk("p","lead","No provider is available yet."));return}S.prov.forEach(function(id){var b=mk("button","po"+(prov===id?" on":"")),im=mk("img");im.src=LG[id];im.alt="";b.appendChild(im);b.appendChild(mk("b",null,NM[id]));b.onclick=function(){prov=id;$$(".po").forEach(function(x){x.classList.toggle("on",x===b)});chk()};l.appendChild(b)})}
$$(".dur button").forEach(function(b){b.onclick=function(){dur=+b.dataset.d;$$(".dur button").forEach(function(x){x.classList.toggle("on",x===b)});chk()}});
function chk(){$("#go").disabled=!(prov&&dur)}
$("#go").onclick=function(){buildTask({provider:prov,hours:dur,steps:dur==12?1:2,done:0,sid:""});gshow("gtask")};
function tsLoad(f){if(window.turnstile)return f();var s=document.createElement("script");s.src="https://challenges.cloudflare.com/turnstile/v0/api.js?render=explicit";s.onload=f;document.head.appendChild(s)}
function buildTask(st){prov=st.provider;dur=st.hours;var n=st.steps,T=$("#tl"),act=st.sid?st.done+1:0;T.innerHTML="";tsw=null;TS="";
for(var i=0;i<=n;i++)(function(i){var d=mk("div","st"+(i<act?" done":i===act?" act":""));d.appendChild(mk("div","dot",i<act?"\u2713":String(i)));d.appendChild(mk("b",null,i?"Step "+i:"Step 0 (Start)"));d.appendChild(mk("p","sd",i?"Complete the "+NM[prov]+" page, then come back.":"Verify you are human to begin."));if(i===0&&!st.sid&&S.ts){tsw=mk("div","tsw");d.appendChild(tsw)}var b=mk("button","btn sm",i?"Open "+NM[prov]:"Start");b.onclick=function(){i?openStep(b):start(b)};if(i<act)b.hidden=true;d.appendChild(b);T.appendChild(d)})(i);
$("#th").textContent=NM[prov]+" \u00b7 "+dur+" Hours \u00b7 "+n+(n>1?" steps":" step");$("#pf").style.width=(st.sid?(st.done+1)/(n+1)*100:0)+"%";
if(tsw)tsLoad(function(){window.turnstile.render(tsw,{sitekey:S.ts,theme:"dark",callback:function(t){TS=t}})})}
function start(b){if(S.ts&&!TS)return toast("Complete the human check first");b.disabled=true;b.textContent="Verifying\u2026";
api("/gk/start",{method:"POST",body:JSON.stringify({provider:prov,hours:dur,ts:TS,renew:renewKey})}).then(function(r){lss("hk_s",r.sid);buildTask({provider:prov,hours:dur,steps:r.steps,done:0,sid:r.sid})}).catch(function(e){b.disabled=false;b.textContent="Start";toast(e.message==="human"?"Human check failed, try again":e.message==="maintenance"?"Under maintenance":e.message==="renew"?"This key cannot be renewed":"Could not start");if(window.turnstile&&tsw)try{window.turnstile.reset(tsw)}catch(x){}})}
function openStep(b){b.disabled=true;b.textContent="Opening\u2026";api("/gk/open",{method:"POST",body:JSON.stringify({sid:lsg("hk_s")})}).then(function(r){location.href=r.url}).catch(function(e){b.disabled=false;b.textContent="Open "+NM[prov];toast("Could not open the link")})}
function after(r){if(r.key)return reveal(r);buildTask({provider:r.provider,hours:r.hours,steps:r.steps,done:r.done,sid:r.sid});gshow("gtask")}
function cb(){var q={};new URLSearchParams(location.search).forEach(function(v,k){q[k]=v});view("getkey");gshow("gtask");$("#th").textContent="Verifying\u2026";$("#tl").innerHTML="";var sid=lsg("hk_s");
if(!sid){history.replaceState(null,"","/getkey");return tabg("p")}
api("/gk/verify",{method:"POST",body:JSON.stringify({sid:sid,params:q})}).then(function(r){history.replaceState(null,"","/getkey");after(r)}).catch(function(e){history.replaceState(null,"","/getkey");toast("Verification failed, try again");tabg("p")})}
var AL="ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnpqrstuvwxyz23456789";
function scr(el,t){var n=0,iv=setInterval(function(){n++;var s="";for(var i=0;i<t.length;i++)s+=(i<n/2||t[i]==="-")?t[i]:AL[Math.floor(Math.random()*AL.length)];el.textContent=s;if(n>=t.length*2){clearInterval(iv);el.textContent=t}},40)}
function reveal(r){lastKey=r.key;var a=mykeys(),ix=-1;a.forEach(function(x,i){if(x.k===r.key)ix=i});if(ix>=0){a[ix].exp=r.exp;a[ix].d=r.hours}else a.unshift({k:r.key,exp:r.exp,d:r.hours});lss("hk_keys",JSON.stringify(a));renewKey="";rnShow();$("#krt").textContent=r.renewed?"Key renewed. It is active again.":"Key created. Copy it and paste it into the script window.";lss("hk_s",null);$("#kx").textContent="Valid for "+r.hours+" hours";gshow("kreveal");scr($("#kv"),r.key)}
$("#kcopy").onclick=function(){navigator.clipboard.writeText(lastKey).then(function(){toast("Key copied")},function(){toast("Could not copy")})};
$("#kview").onclick=function(){tabg("k")};
function mykeys(){try{return JSON.parse(lsg("hk_keys")||"[]")}catch(e){return[]}}
function kdraw(){var l=$("#kl");l.innerHTML="";var ks=mykeys();ks.forEach(function(k,i){var act=k.exp>Date.now(),left=Math.max(0,k.exp-Date.now()),c=mk("div","kr"),t=mk("div","kt");t.appendChild(mk("code",null,k.k));t.appendChild(mk("span","chip "+(act?"on":"off"),act?"ACTIVE":"EXPIRED"));c.appendChild(t);var bar=mk("div","pb"),f=mk("i");f.style.width=(left/(k.d*36e5)*100)+"%";bar.appendChild(f);c.appendChild(bar);c.appendChild(mk("small",null,act?Math.floor(left/36e5)+"h "+Math.floor(left%36e5/6e4)+"m left":"Expired"));var a=mk("div","ka"),cp=mk("button","btn ghost sm","COPY");cp.onclick=function(){navigator.clipboard.writeText(k.k).then(function(){toast("Key copied")})};a.appendChild(cp);if(!act){var r=mk("button","btn sm","RENEW");r.onclick=function(){renewKey=k.k;tabg("p");rnShow()};a.appendChild(r)}var d=mk("button","btn ghost sm","DELETE");d.onclick=function(){ks.splice(i,1);lss("hk_keys",JSON.stringify(ks));kdraw()};a.appendChild(d);c.appendChild(a);l.appendChild(c)});if(!ks.length)l.appendChild(mk("p","lead c","No keys yet."))}
function pad(n){return(n<10?"0":"")+n}

/* Admin */
function strip(){return{games:S.games.map(function(g){return{link:g.link,label:g.label,status:g.status}}),loader:S.loader,links:S.links,executors:S.executors,shop:S.shop,ann:S.ann,maint:S.maint,set:S.set}}
function save(refresh){return api("/admin/state",{method:"PUT",body:JSON.stringify(strip())}).then(function(){toast("Saved");if(refresh)return api("/admin/state").then(function(d){S=d;gdraw()})}).catch(function(){toast("Save failed")})}
function sel(o,v,f){var s=document.createElement("select");o.forEach(function(x){s.appendChild(mk("option",null,x))});s.value=v;s.onchange=function(){f(s.value)};return s}
function gdraw(){var l=$("#glist");l.innerHTML="";S.games.forEach(function(g,i){var d=mk("div","game ag");d.appendChild(thumb(g));var m=mk("div");m.appendChild(mk("span","n",g.name||"Game"));m.appendChild(mk("small",null,g.link));d.appendChild(m);var c=mk("div","ctl");c.appendChild(sel(["Key system","Keyless","Both"],g.label,function(v){g.label=v;save()}));c.appendChild(sel(["Working","Updating","Down"],g.status,function(v){g.status=v;save()}));var b=mk("button","btn ghost sm","Delete");b.onclick=function(){S.games.splice(i,1);gdraw();save()};c.appendChild(b);d.appendChild(c);l.appendChild(d)});gopt()}
function gopt(){var s=$("#cg"),v=s.value||"all";s.innerHTML="";var a=mk("option",null,"All");a.value="all";s.appendChild(a);S.games.forEach(function(g){if(g.uni){var o=mk("option",null,g.name||"Game");o.value=String(g.uni);s.appendChild(o)}});s.value=v;if(s.value!==v)s.value="all"}
function sl(id,arr,n){var el=$("#"+id);el.innerHTML="";arr.forEach(function(r,i){var d=mk("div","sr");for(var k=0;k<n;k++)(function(k){var x=document.createElement("input");x.value=n>1?r[k]:r;x.onchange=function(){if(n>1)r[k]=x.value;else arr[i]=x.value;save()};d.appendChild(x)})(k);var b=mk("button","btn ghost sm","Delete");b.onclick=function(){arr.splice(i,1);shopDraw();save()};d.appendChild(b);el.appendChild(d)})}
function shopDraw(){sl("sp-r",S.shop.r.prices,2);sl("sp-c",S.shop.c.prices,2);sl("pm-r",S.shop.r.pm,1);sl("pm-c",S.shop.c.pm,1);sl("mm-l",S.shop.mm,2)}
function fdraw(){var l=$("#fl");l.innerHTML="";(S.feedback||[]).forEach(function(f){var d=mk("div","fb");d.appendChild(mk("div",null,f.message));d.appendChild(mk("small",null,new Date(f.at).toLocaleString()+" "));var b=mk("button","btn ghost sm","Delete");b.onclick=function(){api("/admin/feedback/delete",{method:"POST",body:JSON.stringify({at:f.at})}).then(function(){S.feedback=S.feedback.filter(function(x){return x.at!==f.at});fdraw()}).catch(function(){toast("Delete failed")})};d.appendChild(b);l.appendChild(d)});if(!(S.feedback||[]).length)l.appendChild(mk("p","lead","No feedback yet."))}
function setFill(){var p=S.set.p;PV.forEach(function(x){$("#"+x[0]+"1").value=p[x[1]].link;$("#"+x[0]+"2").value=p[x[1]].token});$("#ts1").value=S.set.ts.site;$("#ts2").value=S.set.ts.secret;$("#h1").value=S.set.hooks.key;$("#h2").value=S.set.hooks.exec;$("#an1").value=S.ann.on?"On":"Off";$("#an2").value=S.ann.text;$("#mt1").value=S.maint.on?"On":"Off";$("#mt2").value=S.maint.text;$("#cbu").value=location.origin+"/cb";$("#dc1").value=S.set.dc.token;$("#dc2").value=S.set.dc.app;$("#dc3").value=S.set.dc.pub;$("#dcu").value=location.origin+"/discord"}
var PV=[["sl","lootlabs"],["sv","linkvertise"],["sc","cutyio"],["sk","lockr"]];
function saveSettings(){var v=function(i){return $("#"+i).value.trim()},p={};PV.forEach(function(x){p[x[1]]={link:v(x[0]+"1"),token:v(x[0]+"2")}});S.set={p:p,hooks:{key:v("h1"),exec:v("h2")},ts:{site:v("ts1"),secret:v("ts2")},dc:{token:v("dc1"),app:v("dc2"),pub:v("dc3")}};S.ann={on:$("#an1").value==="On",text:v("an2")};S.maint={on:$("#mt1").value==="On",text:v("mt2")};return save()}
$("#esave").onclick=saveSettings;
$("#dcreg").onclick=function(){saveSettings().then(function(){return api("/admin/discord/register",{method:"POST"})}).then(function(r){toast(r.ok?"Commands registered ("+r.count+")":(r.error||"Failed"))}).catch(function(){toast("Failed")})};
$("#cbc").onclick=function(){navigator.clipboard.writeText($("#cbu").value).then(function(){toast("Copied")})};
$("#cmk").onclick=function(){api("/admin/key/create",{method:"POST",body:JSON.stringify({type:$("#ct").value,unit:$("#cu").value,amount:+$("#ca").value||1,game:$("#cg").value})}).then(function(r){var o=$("#cout");o.innerHTML="";o.appendChild(mk("code",null,r.key));var b=mk("button","btn ghost sm","Copy");b.onclick=function(){navigator.clipboard.writeText(r.key).then(function(){toast("Copied")})};o.appendChild(b);toast("Key created")}).catch(function(){toast("Could not create the key")})};
function kload(){api("/admin/keys?q="+encodeURIComponent($("#kq").value.trim())).then(function(r){var l=$("#kls");l.innerHTML="";r.keys.forEach(function(k){var c=mk("div","kr"),t=mk("div","kt");t.appendChild(mk("code",null,k.key));var st=k.rv?"REVOKED":(k.exp&&k.exp<Date.now())?"EXPIRED":"ACTIVE";t.appendChild(mk("span","chip "+(st==="ACTIVE"?"on":"off"),st));c.appendChild(t);c.appendChild(mk("small",null,k.type+" \u00b7 "+(k.g&&k.g!=="all"?k.gn||"one game":"All games")+" \u00b7 "+(k.exp?"expires "+new Date(k.exp).toLocaleString():"forever")+" \u00b7 "+(k.uid?"bound to "+k.uid:"not bound yet")));var a=mk("div","ka");[[k.rv?"Restore":"Revoke","revoke"],["+24h","extend"],["Delete","delete"]].forEach(function(x){var b=mk("button","btn ghost sm",x[0]);b.onclick=function(){api("/admin/key/action",{method:"POST",body:JSON.stringify({key:k.key,action:x[1],hours:24})}).then(kload)};a.appendChild(b)});c.appendChild(a);l.appendChild(c)});if(!r.keys.length)l.appendChild(mk("p","lead","No keys found."))}).catch(function(){toast("Could not load keys")})}
var kt=0;$("#kq").oninput=function(){clearTimeout(kt);kt=setTimeout(kload,300)};
function dload(){api("/admin/logs").then(function(r){var g=$("#dbg");g.innerHTML="";r.dbg.forEach(function(x){g.appendChild(mk("div","fb",new Date(x.at).toLocaleString()+" \u00b7 "+x.m))});if(!r.dbg.length)g.appendChild(mk("p","lead","Nothing yet."))}).catch(function(){toast("Could not load")})}
function sload(){api("/admin/stats").then(function(r){var l=$("#sts");l.innerHTML="";[["Keys total",r.keysTotal],["Keys active",r.keysActive],["Premium keys",r.premium],["Keys bound to an account",r.bound],["Keys created",r.created]].forEach(function(x){var d=mk("div","price");d.appendChild(mk("span",null,x[0]));d.appendChild(mk("span",null,String(x[1])));l.appendChild(d)})}).catch(function(){toast("Could not load stats")})}
function load(){return api("/admin/state").then(function(d){S=d;S.executors=S.executors||[];$("#gate").hidden=true;$("#panel").hidden=false;gdraw();exdraw();shopDraw();fdraw();setFill();$("#lo").value=S.loader;$("#k2").value=S.links.discord;$("#k3").value=S.links.telegram})}
$$(".tabs button").forEach(function(b){b.onclick=function(){var t=b.dataset.t;$$(".tabs button").forEach(function(x){x.classList.toggle("on",x===b)});$$(".t").forEach(function(e){e.hidden=e.dataset.t!==t});if(t==="y")kload();if(t==="e")dload();if(t==="a")sload()}});
$("#gadd").onclick=function(){var u=$("#gl").value.trim();if(!/roblox\.com\/games\/\d+/.test(u))return toast("Paste a Roblox game link");S.games.push({link:u,label:$("#gm").value,status:$("#gs").value});$("#gl").value="";gdraw();save(true)};

var EXS=["Supported","Not supported","Not tested"];
function exdraw(){var l=$("#exl");l.innerHTML="";S.executors.forEach(function(x,i){var c=mk("div","kr");[["name","Name"],["logo","Logo (image URL, optional)"],["link","Link"]].forEach(function(f){var n=document.createElement("input");n.placeholder=f[1];n.value=x[f[0]]||"";n.onchange=function(){x[f[0]]=n.value.trim();save()};c.appendChild(n)});var a=mk("div","ka");a.appendChild(sel(EXS,x.status,function(v){x.status=v;save()}));var d=mk("button","btn ghost sm","Delete");d.onclick=function(){S.executors.splice(i,1);exdraw();save()};a.appendChild(d);c.appendChild(a);l.appendChild(c)});if(!S.executors.length)l.appendChild(mk("p","lead","No executors yet."))}
$("#exadd").onclick=function(){var n=$("#ex1").value.trim();if(!n)return toast("Enter a name");S.executors.push({name:n,logo:$("#ex2").value.trim(),link:$("#ex3").value.trim(),status:$("#ex4").value});$("#ex1").value=$("#ex2").value=$("#ex3").value="";exdraw();save()};
$$("#asg button").forEach(function(b){b.onclick=function(){$$("#asg button").forEach(function(x){x.classList.toggle("on",x===b)});$("#ag1").hidden=b.dataset.ag!=="g";$("#ag2").hidden=b.dataset.ag!=="e"}});
$("#lsave").onclick=function(){S.loader=$("#lo").value;save()};
$("#ksave").onclick=function(){S.links={discord:$("#k2").value.trim(),telegram:$("#k3").value.trim()};save()};
$("#sadd").onclick=function(){var d=$("#ad").value.trim(),p=$("#ap").value.trim();if(!d||!p)return toast("Enter duration and price");S.shop[$("#ao").value].prices.push([d,p]);$("#ad").value=$("#ap").value="";shopDraw();save()};
$("#padd").onclick=function(){var n=$("#an").value.trim();if(!n)return toast("Enter a name");S.shop[$("#ag").value].pm.push(n);$("#an").value="";shopDraw();save()};
$("#madd").onclick=function(){var n=$("#mn").value.trim(),u=$("#mu").value.trim();if(!n||!u)return toast("Enter a name and link");S.shop.mm.push([n,u]);$("#mn").value=$("#mu").value="";shopDraw();save()};
$("#enter").onclick=function(){var v=$("#key").value.trim();if(!v)return toast("Enter your key");key=v;api("/admin/login",{method:"POST"}).then(function(){try{sessionStorage.setItem("hk",key)}catch(e){}return load()}).catch(function(e){key="";toast(e.status==429?"Too many attempts, try again later":"Wrong key")})};
$("#key").addEventListener("keydown",function(e){if(e.key==="Enter")$("#enter").click()});

if(admin){try{key=sessionStorage.getItem("hk")||""}catch(e){}if(key)load().catch(function(){key=""})}
else api("/state").then(function(d){S=d;render();if(location.pathname==="/cb")cb();else route()}).catch(function(){toast("Could not load the site data")});
(function(){var c=$("#fire"),x=c.getContext("2d"),W,H,P=[],still=matchMedia("(prefers-reduced-motion:reduce)").matches;
function rs(){W=c.width=innerWidth;H=c.height=Math.round(innerHeight*.55)}rs();addEventListener("resize",rs);
function mk(init){return{x:Math.random()*W,y:H+10-(init?Math.random()*H:0),r:20+Math.random()*34,v:.6+Math.random()*1.6,s:(Math.random()-.5)*.6}}
for(var i=0;i<70;i++)P.push(mk(1));
function f(){x.globalCompositeOperation="source-over";x.clearRect(0,0,W,H);x.globalCompositeOperation="lighter";
P.forEach(function(p,i){p.y-=p.v;p.x+=p.s+Math.sin((p.y+i*9)/38)*.5;p.r*=.994;
if(p.y<-20||p.r<5){P[i]=mk(0);return}
var a=Math.max(0,p.y/H)*.55+.03,g=x.createRadialGradient(p.x,p.y,0,p.x,p.y,p.r);
g.addColorStop(0,"rgba(235,200,255,"+a+")");g.addColorStop(.35,"rgba(155,109,255,"+a*.7+")");g.addColorStop(1,"rgba(90,30,200,0)");
x.fillStyle=g;x.beginPath();x.arc(p.x,p.y,p.r,0,6.3);x.fill()});
if(!still)requestAnimationFrame(f)}f()})();
})();
</script>
</body>
